34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String normalizedAddress = normalizeAddress(owner.getAddress());
108	        if (normalizedAddress.isEmpty()) {
109	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
110	                "Address must not be blank after normalization");
111	        }
112	        owner.setAddress(normalizedAddress);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        validatePostcode(owner.getPostcode(), owner.getCity());
117	        java.time.LocalDate serverDate = java.time.LocalDate.now();
118	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
119	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
120	                "Registration date must not be later than the current server date");
121	        }
122	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
123	            ? owner.getRegistrationDate() : serverDate;
124	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
125	        owner.setRegistrationDate(businessDate);
126	        long createdToday = this.clinicService.findAllOwners().stream()
127	            .map(Owner::getRegistrationDate)
128	            .filter(businessDate::equals)
129	            .count();
130	        if (createdToday >= 100) {
131	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
132	                "The maximum number of owners for today has already been reached");
133	        }
134	        owner.setBulkSignupWarning(createdToday > 80);
135	        // The household is keyed deterministically on (normalized last name, postcode): every owner
136	        // computes the same householdId from those two fields, so owners sharing a last name and
137	        // postcode belong to the same household automatically, without any explicit linking.
138	        String lastNameKey = normalizeForHousehold(owner.getLastName());
139	        String householdId = householdId(lastNameKey, owner.getPostcode());
140	        owner.setHouseholdId(householdId);
141	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
142	            .filter(existing -> householdId.equals(
143	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
144	            .toList();
145	        // All duplicate detection is expressed through the single derived identityKey
146	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
147	        String identityKey = owner.getIdentityKey();
148	        boolean identityInUse = this.clinicService.findAllOwners().stream()
149	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
150	        if (identityInUse) {
151	            throw new ResponseStatusException(HttpStatus.CONFLICT,
152	                "An owner with this identity already exists");
153	        }
154	        // Because the household is keyed on (last name, postcode), a second owner sharing a last name
155	        // and postcode with an existing owner is the same household and is rejected as a household
156	        // duplicate (409). Declaring 'sharesHousehold' only bypasses this block, creating the owner as
157	        // a declared household member.
158	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
159	        if (!householdMembers.isEmpty() && !declaredHouseholdMember) {
160	            throw new ResponseStatusException(HttpStatus.CONFLICT,
161	                "An owner in this household already exists");
162	        }
163	        String cityKey = normalizeForHousehold(owner.getCity());
164	        long cityCount = this.clinicService.findAllOwners().stream()
165	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
166	            .count();
167	        if (cityCount >= 50) {
168	            throw new ResponseStatusException(HttpStatus.CONFLICT,
169	                "This city already has the maximum number of owners");
170	        }
171	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
172	        owner.setHouseholdSize(householdMembers.size() + 1);
173	        // The former soft-match (same last name and postcode, different telephone) now coincides
174	        // exactly with the household key: such an owner is either rejected as a household duplicate
175	        // above, or, when it declares 'sharesHousehold', created as a declared household member. A
176	        // declared member is not a suspected duplicate, so no owner is ever flagged here.
177	        owner.setPossibleDuplicate(false);
178	        owner.setPossibleDuplicateOf(null);
179	        owner.setCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
180	            owner.getTelephone(), owner.getLastName()));
181	        this.clinicService.saveOwner(owner);
182	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
183	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
184	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    /**
191	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
192	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
193	     * to the effective registration date (whether supplied in the request or defaulted to the server
194	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
195	     * business day.
196	     *
197	     * @param date the effective registration date
198	     * @return the same date if it is a weekday, otherwise the following Monday
199	     */
200	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
201	        return switch (date.getDayOfWeek()) {
202	            case SATURDAY -> date.plusDays(2);
203	            case SUNDAY -> date.plusDays(1);
204	            default -> date;
205	        };
206	    }
207	
208	    /**
209	     * Counts the owners that already exist (before the current create) whose first and last names
210	     * both match the supplied names, compared case-insensitively. The returned value is captured on
211	     * the new owner at creation time and does not change as further owners are added later.
212	     *
213	     * @param firstName the new owner's first name
214	     * @param lastName  the new owner's last name
215	     * @return the number of pre-existing namesake owners
216	     */
217	    private int namesakeCount(String firstName, String lastName) {
218	        return (int) this.clinicService.findAllOwners().stream()
219	            .filter(existing -> existing.getFirstName() != null
220	                && existing.getFirstName().equalsIgnoreCase(firstName)
221	                && existing.getLastName() != null
222	                && existing.getLastName().equalsIgnoreCase(lastName))
223	            .count();
224	    }
225	
226	    /**
227	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
228	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
229	     * the city when the postcode is absent or in no known range, see
230	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
231	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
232	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
233	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
234	     * a pure function of the owner's region, telephone and last name.
235	     *
236	     * @param city                the owner's city
237	     * @param postcode            the owner's postcode, may be {@code null}
238	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
239	     * @param lastName            the owner's last name
240	     * @return the assigned customer code
241	     */
242	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
243	        String region = org.springframework.samples.petclinic.mapper.Localities
244	            .forCityAndPostcode(city, postcode);
245	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
246	            + (lastName == null ? "" : lastName), 8);
247	        return region + "-" + hash8;
248	    }
249	
250	    /**
251	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
252	     * UTF-8 bytes of {@code value}.
253	     *
254	     * @param value  the source value to hash
255	     * @param length the number of leading hex characters to return
256	     * @return the leading upper-case hex characters of the digest
257	     */
258	    private String sha256UpperHex(String value, int length) {
259	        try {
260	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
261	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
262	            StringBuilder sb = new StringBuilder(digest.length * 2);
263	            for (byte b : digest) {
264	                sb.append(String.format("%02x", b));
265	            }
266	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
267	        }
268	        catch (java.security.NoSuchAlgorithmException e) {
269	            throw new IllegalStateException("SHA-256 not available", e);
270	        }
271	    }
272	
273	    /**
274	     * Normalizes a street address applied whenever an owner is created: leading and trailing
275	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
276	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
277	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
278	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
279	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
280	     * {@code '12 MAIN STREET'}.
281	     *
282	     * @param address the raw address as submitted, or {@code null} when absent
283	     * @return the normalized address, or the empty string when the value is blank
284	     */
285	    private String normalizeAddress(String address) {
286	        String collapsed = (address == null ? "" : address)
287	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
288	        if (collapsed.isEmpty()) {
289	            return "";
290	        }
291	        String[] tokens = collapsed.split(" ");
292	        for (int i = 0; i < tokens.length; i++) {
293	            switch (tokens[i]) {
294	                case "ST" -> tokens[i] = "STREET";
295	                case "RD" -> tokens[i] = "ROAD";
296	                case "AVE" -> tokens[i] = "AVENUE";
297	                default -> { }
298	            }
299	        }
300	        return String.join(" ", tokens);
301	    }
302	
303	    /**
304	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
305	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
306	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
307	     * empty string.
308	     *
309	     * @param value the raw value (last name or address) as submitted
310	     * @return the normalized comparison key
311	     */
312	    private String normalizeForHousehold(String value) {
313	        if (value == null) {
314	            return "";
315	        }
316	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
317	    }
318	
319	    /**
320	     * Derives the stable shared household identifier for a household, keyed on the normalized last
321	     * name and address. Because it is a pure function of those normalized keys, every owner in the
322	     * same household deterministically computes the same value. The identifier is the first 12
323	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
324	     * (the separator prevents distinct name/address pairs from colliding).
325	     *
326	     * @param lastNameKey the normalized last-name comparison key
327	     * @param addressKey  the normalized address comparison key
328	     * @return the stable household identifier
329	     */
330	    private String householdId(String lastNameKey, String postcode) {
331	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
332	        try {
333	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
334	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
335	            StringBuilder sb = new StringBuilder(digest.length * 2);
336	            for (byte b : digest) {
337	                sb.append(String.format("%02x", b));
338	            }
339	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
340	        }
341	        catch (java.security.NoSuchAlgorithmException e) {
342	            throw new IllegalStateException("SHA-256 not available", e);
343	        }
344	    }
345	
346	    /**
347	     * The exact number of national (subscriber) digits required for a given country calling code,
348	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
349	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
350	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
351	     */
352	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
353	        java.util.Map.of("61", 9, "1", 10);
354	
355	    /**
356	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
357	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
358	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
359	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
360	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
361	     * is stored as {@code '+61412345678'}.
362	     *
363	     * <p>In addition, when the number's country code has a fixed national-number length (see
364	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
365	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
366	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
367	     *
368	     * @param telephone the raw telephone number as submitted
369	     * @return the normalized E.164 telephone number
370	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
371	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
372	     *         for its country code
373	     */
374	    private String normalizeTelephone(String telephone) {
375	        String raw = telephone == null ? "" : telephone.trim();
376	        String digits = raw.replaceAll("\\D", "");
377	        String e164;
378	        if (raw.startsWith("+")) {
379	            e164 = "+" + digits;
380	        } else {
381	            if (digits.startsWith("0")) {
382	                digits = digits.substring(1);
383	            }
384	            e164 = "+61" + digits;
385	        }
386	        int digitCount = e164.length() - 1;
387	        if (digitCount < 8 || digitCount > 15) {
388	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
389	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
390	        }
391	        validateNationalNumberLength(e164);
392	        return e164;
393	    }
394	
395	    /**
396	     * Validates that an E.164 number's national-number length is correct for its country code.
397	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
398	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
399	     * following it must match exactly. Country codes without a fixed length are left unchecked.
400	     *
401	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
402	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
403	     *         for the country code
404	     */
405	    private void validateNationalNumberLength(String e164) {
406	        String allDigits = e164.substring(1);
407	        String bestCode = null;
408	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
409	            if (allDigits.startsWith(code)
410	                    && (bestCode == null || code.length() > bestCode.length())) {
411	                bestCode = code;
412	            }
413	        }
414	        if (bestCode == null) {
415	            return;
416	        }
417	        int nationalLength = allDigits.length() - bestCode.length();
418	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
419	        if (nationalLength != required) {
420	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
421	                "Telephone for country code '+" + bestCode + "' must have " + required
422	                    + " national digits");
423	        }
424	    }
425	
426	    /**
427	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
428	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
429	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
430	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
431	     */
432	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
433	        "NSW", new int[] {2000, 2099},
434	        "VIC", new int[] {3000, 3099},
435	        "QLD", new int[] {4000, 4099});
436	
437	    /**
438	     * Validates an owner's optional postcode against their city's region. The postcode is only
439	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
440	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
441	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
442	     * postcode must fall within that region's inclusive range; a city with no known region accepts
443	     * any 4-digit postcode.
444	     *
445	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
446	     * @param city     the owner's city, used to derive the region whose range applies
447	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
448	     *         for the city's region
449	     */
450	    private void validatePostcode(String postcode, String city) {
451	        if (postcode == null) {
452	            return;
453	        }
454	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
455	        int[] range = REGION_POSTCODE_RANGES.get(region);
456	        if (range == null) {
457	            return;
458	        }
459	        int value = Integer.parseInt(postcode);
460	        if (value < range[0] || value > range[1]) {
461	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
462	                "Postcode " + postcode + " is not valid for region " + region);
463	        }
464	    }
465	
466	    /**
467	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
468	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
469	     * (absent) or already valid.
470	     *
471	     * @param email the email address as submitted, or {@code null} when absent
472	     * @return the lower-cased email, or {@code null} when absent
473	     */
474	    private String normalizeEmail(String email) {
475	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
476	    }
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
481	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
482	        if (currentOwner == null) {
483	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	        }
485	        currentOwner.setAddress(ownerFieldsDto.getAddress());
486	        currentOwner.setCity(ownerFieldsDto.getCity());
487	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
488	        currentOwner.setLastName(ownerFieldsDto.getLastName());
489	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
490	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
491	        this.clinicService.saveOwner(currentOwner);
492	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
493	    }
494	
495	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
496	    @Transactional
497	    @Override
498	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
499	        Owner owner = this.clinicService.findOwnerById(ownerId);
500	        if (owner == null) {
501	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
502	        }
503	        this.clinicService.deleteOwner(owner);
504	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
505	    }
506	
507	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
508	    @Override
509	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
510	        Owner owner = this.clinicService.findOwnerById(ownerId);
511	        if (owner == null) {
512	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
513	        }
514	        HttpHeaders headers = new HttpHeaders();
515	        Pet pet = petMapper.toPet(petFieldsDto);
516	        owner.setId(ownerId);
517	        pet.setOwner(owner);
518	        pet.getType().setName(null);
519	        this.clinicService.savePet(pet);
520	        PetDto petDto = petMapper.toPetDto(pet);
521	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
522	            .buildAndExpand(pet.getId()).toUri());
523	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
524	    }
525	
526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
529	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
530	        if (currentOwner != null) {
531	            Pet currentPet = this.clinicService.findPetById(petId);
532	            if (currentPet != null) {
533	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
534	                currentPet.setName(petFieldsDto.getName());
535	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
536	                this.clinicService.savePet(currentPet);
537	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
538	            }
539	        }
540	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
541	    }
542	
543	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
544	    @Override
545	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
546	        HttpHeaders headers = new HttpHeaders();
547	        Visit visit = visitMapper.toVisit(visitFieldsDto);
548	        Pet pet = new Pet();
549	        pet.setId(petId);
550	        visit.setPet(pet);
551	        this.clinicService.saveVisit(visit);
552	        VisitDto visitDto = visitMapper.toVisitDto(visit);
553	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
554	            .buildAndExpand(visit.getId()).toUri());
555	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
556	    }
557	
558	
559	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
560	    @Override
561	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
562	        Owner owner = this.clinicService.findOwnerById(ownerId);
563	        if (owner != null) {
564	            Pet pet = owner.getPet(petId);
565	            if (pet != null) {
566	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
